window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e423410c9c08e452"]={"versions": [{"id": "FIG-e423410c9c08e452", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR M2-Metamodell-Ausschnitt (Meta-Modeling).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation der M2-Klassenstruktur zur Konfiguration des UDS-Dienstes <em>RequestFileTransfer</em> (SID 0x38 gemäß ISO 14229-1) innerhalb des AUTOSAR Diagnostic Extract Templates (<code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, Release R4.2.2). Das Modell trennt generische Dienstdefinitionen (Klassenebene) von der konkreten ECU-spezifischen Ausprägung (Instanzebene) sowie der Zugriffsrechteverwaltung (Sessions, Security Access).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Metaklassen:</strong></li>\n<li><code>DiagnosticServiceClass</code> <em>(abstract)</em>: Basisklasse aller UDS-Dienstklassen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><strong>Attribut:</strong> <code>+accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> – Legt fest, ob Zugriffsrechte zentral auf Klassenebene oder granular auf Instanzebene evaluiert werden.</li>\n<li><code>DiagnosticServiceInstance</code> <em>(abstract)</em>: Basisklasse für konkrete Dienstinstanzen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticAccessPermission</code>: Definiert Sicherheitsstufen (<code>DiagnosticSecurityLevel</code>) und Diagnose-Sitzungen (<code>DiagnosticSession</code>), unter denen der Zugriff erlaubt ist; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticRequestFileTransferClass</code>: Konkrete Spezialisierung von <code>DiagnosticServiceClass</code> für SID 0x38.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Konkrete Spezialisierung von <code>DiagnosticServiceInstance</code> für SID 0x38.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen, Assoziationen & Kardinalitäten:</strong></li>\n<li><strong>Vererbungen (Generalization):</strong></li>\n<li><code>DiagnosticRequestFileTransfer</code> $\\rightarrow$ <code>DiagnosticServiceInstance</code></li>\n<li><code>DiagnosticRequestFileTransferClass</code> $\\rightarrow$ <code>DiagnosticServiceClass</code></li>\n<li><strong>Klassen-/Instanz-Kopplung:</strong></li>\n<li><code>DiagnosticServiceInstance</code> referenziert <code>DiagnosticServiceClass</code> über Rolle <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>).</li>\n<li><code>DiagnosticRequestFileTransfer</code> redefiniert diese Assoziation auf die konkrete Klasse <code>DiagnosticRequestFileTransferClass</code> über Rolle <code>+requestFileTransferClass</code> (Kardinalität <code>1</code>, Eigenschaft <code>{redefines serviceClass}</code>). Jede Instanz erfordert genau eine zugeordnete Dienstklasse.</li>\n<li><strong>Zugriffssteuerungs-Assoziationen (<code>+accessPermission</code>, Kardinalität jeweils <code>0..1</code>):</strong></li>\n<li>Assoziation von <code>DiagnosticServiceClass</code> zu <code>DiagnosticAccessPermission</code>.</li>\n<li>Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-spezifische Auswertung:</strong> Als statisches M2-Strukturdiagramm enthält das Schaubild keine direkten Laufzeitsequenzen; es steuert jedoch die Validierungslogik im BSW-Diagnosestack (<code>Dcm</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Anfrage-Validierung:</strong> Bei Empfang einer UDS-PDU mit SID 0x38 prüft der <code>Dcm</code> die Zugriffsrechte anhand der über <code>accessPermissionValidity</code> konfigurierten Ebene (<code>ServiceClass</code> vs. <code>ServiceInstance</code>).</li>\n<li><strong>Zugriffsprüfung:</strong> Validierung gegen aktuelle aktive Session und Security Level (<code>DiagnosticAccessPermission</code>). Bei Nichtübereinstimmung erfolgt die NRC-Rückmeldung (z. B. <code>0x33 SecurityAccessDenied</code> oder <code>0x7E SubFunctionNotSupportedInActiveSession</code>).</li>\n<li><strong>Dispatchen:</strong> Bei positivem Befund Weiterleitung der Dateitransfer-Parameter (z. B. AddFile, DeleteFile, ReadFile) an die zugeordnete Applikations- oder Speicherschnittstelle.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DEXT-Generierung & BSW-Konfiguration (TPS_DEXT_01090):</strong></li>\n<li>DEXT-Importfilter müssen <code>DiagnosticRequestFileTransfer</code> zwingend mit genau einer Instanz von <code>DiagnosticRequestFileTransferClass</code> verknüpfen (<code>Kardinalität 1</code>).</li>\n<li>Die BSW-Generierung übersetzt diese M2-Elemente in die BSW-Konfigurationsstrukturen des <code>Dcm</code> (z. B. <code>DcmDsdService</code>, <code>DcmDsdServiceRow</code>).</li>\n<li><strong>Zugriffsrechte-Konsistenz (<code>accessPermissionValidity</code>):</strong></li>\n<li>Konfigurationswerkzeuge müssen sicherstellen: Ist <code>accessPermissionValidity</code> auf Instanzebene gesetzt, muss <code>DiagnosticRequestFileTransfer.accessPermission</code> definiert sein; ist sie auf Klassenebene gesetzt, muss <code>DiagnosticRequestFileTransferClass.accessPermission</code> gepflegt sein. Konflikte oder inkonsistente Redefinitionen führen zu Schema- bzw. Modellvalidierungsfehlern.</li>\n<li><strong>Applikationsvertrag:</strong></li>\n<li>Für eingebettete Entwickler bestimmt die Instanziierung von <code>DiagnosticRequestFileTransfer</code>, ob der Dienst 0x38 im Dcm-Dispatching aktiviert wird und welche Callback-/Port-Interfaces (<code>Dcm_RequestFileTransfer</code> bzw. entsprechende RTE-Ports) zur Verarbeitung des Dateisystems auf Applikationsebene implementiert werden müssen.</li>\n</ul>"}, {"id": "FIG-eeae68f3e72758d0", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR M2-Metamodell-Ausschnitt (Meta-Modeling).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation der M2-Klassenstruktur zur Konfiguration des UDS-Dienstes <em>RequestFileTransfer</em> (SID 0x38 gemäß ISO 14229-1) innerhalb des AUTOSAR Diagnostic Extract Templates (<code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, Release R4.2.2). Das Modell trennt generische Dienstdefinitionen (Klassenebene) von der konkreten ECU-spezifischen Ausprägung (Instanzebene) sowie der Zugriffsrechteverwaltung (Sessions, Security Access).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Metaklassen:</strong></li>\n<li><code>DiagnosticServiceClass</code> <em>(abstract)</em>: Basisklasse aller UDS-Dienstklassen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><strong>Attribut:</strong> <code>+accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> – Legt fest, ob Zugriffsrechte zentral auf Klassenebene oder granular auf Instanzebene evaluiert werden.</li>\n<li><code>DiagnosticServiceInstance</code> <em>(abstract)</em>: Basisklasse für konkrete Dienstinstanzen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticAccessPermission</code>: Definiert Sicherheitsstufen (<code>DiagnosticSecurityLevel</code>) und Diagnose-Sitzungen (<code>DiagnosticSession</code>), unter denen der Zugriff erlaubt ist; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticRequestFileTransferClass</code>: Konkrete Spezialisierung von <code>DiagnosticServiceClass</code> für SID 0x38.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Konkrete Spezialisierung von <code>DiagnosticServiceInstance</code> für SID 0x38.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen, Assoziationen & Kardinalitäten:</strong></li>\n<li><strong>Vererbungen (Generalization):</strong></li>\n<li><code>DiagnosticRequestFileTransfer</code> $\\rightarrow$ <code>DiagnosticServiceInstance</code></li>\n<li><code>DiagnosticRequestFileTransferClass</code> $\\rightarrow$ <code>DiagnosticServiceClass</code></li>\n<li><strong>Klassen-/Instanz-Kopplung:</strong></li>\n<li><code>DiagnosticServiceInstance</code> referenziert <code>DiagnosticServiceClass</code> über Rolle <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>).</li>\n<li><code>DiagnosticRequestFileTransfer</code> redefiniert diese Assoziation auf die konkrete Klasse <code>DiagnosticRequestFileTransferClass</code> über Rolle <code>+requestFileTransferClass</code> (Kardinalität <code>1</code>, Eigenschaft <code>{redefines serviceClass}</code>). Jede Instanz erfordert genau eine zugeordnete Dienstklasse.</li>\n<li><strong>Zugriffssteuerungs-Assoziationen (<code>+accessPermission</code>, Kardinalität jeweils <code>0..1</code>):</strong></li>\n<li>Assoziation von <code>DiagnosticServiceClass</code> zu <code>DiagnosticAccessPermission</code>.</li>\n<li>Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-spezifische Auswertung:</strong> Als statisches M2-Strukturdiagramm enthält das Schaubild keine direkten Laufzeitsequenzen; es steuert jedoch die Validierungslogik im BSW-Diagnosestack (<code>Dcm</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Anfrage-Validierung:</strong> Bei Empfang einer UDS-PDU mit SID 0x38 prüft der <code>Dcm</code> die Zugriffsrechte anhand der über <code>accessPermissionValidity</code> konfigurierten Ebene (<code>ServiceClass</code> vs. <code>ServiceInstance</code>).</li>\n<li><strong>Zugriffsprüfung:</strong> Validierung gegen aktuelle aktive Session und Security Level (<code>DiagnosticAccessPermission</code>). Bei Nichtübereinstimmung erfolgt die NRC-Rückmeldung (z. B. <code>0x33 SecurityAccessDenied</code> oder <code>0x7E SubFunctionNotSupportedInActiveSession</code>).</li>\n<li><strong>Dispatchen:</strong> Bei positivem Befund Weiterleitung der Dateitransfer-Parameter (z. B. AddFile, DeleteFile, ReadFile) an die zugeordnete Applikations- oder Speicherschnittstelle.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DEXT-Generierung & BSW-Konfiguration (TPS_DEXT_01090):</strong></li>\n<li>DEXT-Importfilter müssen <code>DiagnosticRequestFileTransfer</code> zwingend mit genau einer Instanz von <code>DiagnosticRequestFileTransferClass</code> verknüpfen (<code>Kardinalität 1</code>).</li>\n<li>Die BSW-Generierung übersetzt diese M2-Elemente in die BSW-Konfigurationsstrukturen des <code>Dcm</code> (z. B. <code>DcmDsdService</code>, <code>DcmDsdServiceRow</code>).</li>\n<li><strong>Zugriffsrechte-Konsistenz (<code>accessPermissionValidity</code>):</strong></li>\n<li>Konfigurationswerkzeuge müssen sicherstellen: Ist <code>accessPermissionValidity</code> auf Instanzebene gesetzt, muss <code>DiagnosticRequestFileTransfer.accessPermission</code> definiert sein; ist sie auf Klassenebene gesetzt, muss <code>DiagnosticRequestFileTransferClass.accessPermission</code> gepflegt sein. Konflikte oder inkonsistente Redefinitionen führen zu Schema- bzw. Modellvalidierungsfehlern.</li>\n<li><strong>Applikationsvertrag:</strong></li>\n<li>Für eingebettete Entwickler bestimmt die Instanziierung von <code>DiagnosticRequestFileTransfer</code>, ob der Dienst 0x38 im Dcm-Dispatching aktiviert wird und welche Callback-/Port-Interfaces (<code>Dcm_RequestFileTransfer</code> bzw. entsprechende RTE-Ports) zur Verarbeitung des Dateisystems auf Applikationsebene implementiert werden müssen.</li>\n</ul>"}, {"id": "FIG-e5517727d9f9a55a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR M2-Metamodell-Ausschnitt (Meta-Modeling).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation der M2-Klassenstruktur zur Konfiguration des UDS-Dienstes <em>RequestFileTransfer</em> (SID 0x38 gemäß ISO 14229-1) innerhalb des AUTOSAR Diagnostic Extract Templates (<code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, Release R4.2.2). Das Modell trennt generische Dienstdefinitionen (Klassenebene) von der konkreten ECU-spezifischen Ausprägung (Instanzebene) sowie der Zugriffsrechteverwaltung (Sessions, Security Access).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Metaklassen:</strong></li>\n<li><code>DiagnosticServiceClass</code> <em>(abstract)</em>: Basisklasse aller UDS-Dienstklassen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticServiceInstance</code> <em>(abstract)</em>: Basisklasse für konkrete Dienstinstanzen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticAccessPermission</code>: Definiert Sicherheitsstufen (<code>DiagnosticSecurityLevel</code>) und Diagnose-Sitzungen (<code>DiagnosticSession</code>), unter denen der Zugriff erlaubt ist; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticRequestFileTransferClass</code>: Konkrete Spezialisierung von <code>DiagnosticServiceClass</code> für SID 0x38.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Konkrete Spezialisierung von <code>DiagnosticServiceInstance</code> für SID 0x38.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen, Assoziationen & Kardinalitäten:</strong></li>\n<li><strong>Vererbungen (Generalization):</strong></li>\n<li><code>DiagnosticRequestFileTransfer</code> $\\rightarrow$ <code>DiagnosticServiceInstance</code></li>\n<li><code>DiagnosticRequestFileTransferClass</code> $\\rightarrow$ <code>DiagnosticServiceClass</code></li>\n<li><strong>Klassen-/Instanz-Kopplung:</strong></li>\n<li><code>DiagnosticServiceInstance</code> referenziert <code>DiagnosticServiceClass</code> über Rolle <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>).</li>\n<li><code>DiagnosticRequestFileTransfer</code> redefiniert diese Assoziation auf die konkrete Klasse <code>DiagnosticRequestFileTransferClass</code> über Rolle <code>+requestFileTransferClass</code> (Kardinalität <code>0..1</code>, Eigenschaft <code>{redefines serviceClass}</code>).</li>\n<li><strong>Zugriffssteuerungs-Assoziation (<code>+accessPermission</code>, Kardinalität <code>0..1</code>):</strong></li>\n<li>Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-spezifische Auswertung:</strong> Als statisches M2-Strukturdiagramm enthält das Schaubild keine direkten Laufzeitsequenzen; es steuert jedoch die Validierungslogik im BSW-Diagnosestack (<code>Dcm</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Anfrage-Validierung:</strong> Bei Empfang einer UDS-PDU mit SID 0x38 identifiziert der <code>Dcm</code> die zugehörige Instanz (<code>DiagnosticRequestFileTransfer</code>).</li>\n<li><strong>Zugriffsprüfung:</strong> Validierung gegen die auf Instanzebene (<code>DiagnosticServiceInstance</code>) zugeordnete <code>DiagnosticAccessPermission</code> (aktive Session und Security Level). Bei Nichtübereinstimmung erfolgt die NRC-Rückmeldung (z. B. <code>0x33 SecurityAccessDenied</code> oder <code>0x7E SubFunctionNotSupportedInActiveSession</code>).</li>\n<li><strong>Dispatchen:</strong> Bei positivem Befund Weiterleitung der Dateitransfer-Parameter (z. B. AddFile, DeleteFile, ReadFile) an die zugeordnete Applikations- oder Speicherschnittstelle.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DEXT-Generierung & BSW-Konfiguration (TPS_DEXT_01090):</strong></li>\n<li>DEXT-Importfilter müssen <code>DiagnosticRequestFileTransfer</code> zwingend mit genau einer Instanz von <code>DiagnosticRequestFileTransferClass</code> verknüpfen (<code>Kardinalität 1</code>).</li>\n<li>Die BSW-Generierung übersetzt diese M2-Elemente in die BSW-Konfigurationsstrukturen des <code>Dcm</code> (z. B. <code>DcmDsdService</code>, <code>DcmDsdServiceRow</code>).</li>\n<li><strong>Zugriffsrechte-Konsistenz (<code>accessPermissionValidity</code>):</strong></li>\n<li>Konfigurationswerkzeuge müssen sicherstellen: Ist <code>accessPermissionValidity</code> auf Instanzebene gesetzt, muss <code>DiagnosticRequestFileTransfer.accessPermission</code> definiert sein; ist sie auf Klassenebene gesetzt, muss <code>DiagnosticRequestFileTransferClass.accessPermission</code> gepflegt sein. Konflikte oder inkonsistente Redefinitionen führen zu Schema- bzw. Modellvalidierungsfehlern.</li>\n<li><strong>Applikationsvertrag:</strong></li>\n<li>Für eingebettete Entwickler bestimmt die Instanziierung von <code>DiagnosticRequestFileTransfer</code>, ob der Dienst 0x38 im Dcm-Dispatching aktiviert wird und welche Callback-/Port-Interfaces (<code>Dcm_RequestFileTransfer</code> bzw. entsprechende RTE-Ports) zur Verarbeitung des Dateisystems auf Applikationsebene implementiert werden müssen.</li>\n</ul>"}, {"id": "FIG-9c0ab4fcccb0161c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR M2-Metamodell-Ausschnitt (Meta-Modeling).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation der M2-Klassenstruktur zur Konfiguration des UDS-Dienstes <em>RequestFileTransfer</em> (SID 0x38 gemäß ISO 14229-1) innerhalb des AUTOSAR Diagnostic Extract Templates (<code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, Release R4.2.2). Das Modell trennt generische Dienstdefinitionen (Klassenebene) von der konkreten ECU-spezifischen Ausprägung (Instanzebene) sowie der Zugriffsrechteverwaltung (Sessions, Security Access).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Metaklassen:</strong></li>\n<li><code>DiagnosticServiceClass</code> <em>(abstract)</em>: Basisklasse aller UDS-Dienstklassen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticServiceInstance</code> <em>(abstract)</em>: Basisklasse für konkrete Dienstinstanzen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticAccessPermission</code>: Definiert Sicherheitsstufen (<code>DiagnosticSecurityLevel</code>) und Diagnose-Sitzungen (<code>DiagnosticSession</code>), unter denen der Zugriff erlaubt ist; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticRequestFileTransferClass</code>: Konkrete Spezialisierung von <code>DiagnosticServiceClass</code> für SID 0x38.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Konkrete Spezialisierung von <code>DiagnosticServiceInstance</code> für SID 0x38.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen, Assoziationen & Kardinalitäten:</strong></li>\n<li><strong>Vererbungen (Generalization):</strong></li>\n<li><code>DiagnosticRequestFileTransfer</code> $\\rightarrow$ <code>DiagnosticServiceInstance</code></li>\n<li><code>DiagnosticRequestFileTransferClass</code> $\\rightarrow$ <code>DiagnosticServiceClass</code></li>\n<li><strong>Klassen-/Instanz-Kopplung:</strong></li>\n<li><code>DiagnosticServiceInstance</code> referenziert <code>DiagnosticServiceClass</code> über Rolle <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>).</li>\n<li><code>DiagnosticRequestFileTransfer</code> redefiniert diese Assoziation auf die konkrete Klasse <code>DiagnosticRequestFileTransferClass</code> über Rolle <code>+requestFileTransferClass</code> (Kardinalität <code>0..1</code>, Eigenschaft <code>{redefines serviceClass}</code>).</li>\n<li><strong>Zugriffssteuerungs-Assoziation (<code>+accessPermission</code>, Kardinalität <code>0..1</code>):</strong></li>\n<li>Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-spezifische Auswertung:</strong> Als statisches M2-Strukturdiagramm enthält das Schaubild keine direkten Laufzeitsequenzen; es steuert jedoch die Validierungslogik im BSW-Diagnosestack (<code>Dcm</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Anfrage-Validierung:</strong> Bei Empfang einer UDS-PDU mit SID 0x38 identifiziert der <code>Dcm</code> die zugehörige Instanz (<code>DiagnosticRequestFileTransfer</code>).</li>\n<li><strong>Zugriffsprüfung:</strong> Validierung gegen die auf Instanzebene (<code>DiagnosticServiceInstance</code>) zugeordnete <code>DiagnosticAccessPermission</code> (aktive Session und Security Level). Bei Nichtübereinstimmung erfolgt die NRC-Rückmeldung (z. B. <code>0x33 SecurityAccessDenied</code> oder <code>0x7E SubFunctionNotSupportedInActiveSession</code>).</li>\n<li><strong>Dispatchen:</strong> Bei positivem Befund Weiterleitung der Dateitransfer-Parameter (z. B. AddFile, DeleteFile, ReadFile) an die zugeordnete Applikations- oder Speicherschnittstelle.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DEXT-Generierung & BSW-Konfiguration (TPS_DEXT_01090):</strong></li>\n<li>DEXT-Importfilter müssen <code>DiagnosticRequestFileTransfer</code> zwingend mit genau einer Instanz von <code>DiagnosticRequestFileTransferClass</code> verknüpfen (<code>Kardinalität 1</code>).</li>\n<li>Die BSW-Generierung übersetzt diese M2-Elemente in die BSW-Konfigurationsstrukturen des <code>Dcm</code> (z. B. <code>DcmDsdService</code>, <code>DcmDsdServiceRow</code>).</li>\n<li><strong>Zugriffsrechte-Konsistenz (<code>accessPermissionValidity</code>):</strong></li>\n<li>Konfigurationswerkzeuge müssen sicherstellen: Ist <code>accessPermissionValidity</code> auf Instanzebene gesetzt, muss <code>DiagnosticRequestFileTransfer.accessPermission</code> definiert sein; ist sie auf Klassenebene gesetzt, muss <code>DiagnosticRequestFileTransferClass.accessPermission</code> gepflegt sein. Konflikte oder inkonsistente Redefinitionen führen zu Schema- bzw. Modellvalidierungsfehlern.</li>\n<li><strong>Applikationsvertrag:</strong></li>\n<li>Für eingebettete Entwickler bestimmt die Instanziierung von <code>DiagnosticRequestFileTransfer</code>, ob der Dienst 0x38 im Dcm-Dispatching aktiviert wird und welche Callback-/Port-Interfaces (<code>Dcm_RequestFileTransfer</code> bzw. entsprechende RTE-Ports) zur Verarbeitung des Dateisystems auf Applikationsebene implementiert werden müssen.</li>\n</ul>"}, {"id": "FIG-86000bdc9202ee87", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / AUTOSAR M2-Metamodell-Ausschnitt (Meta-Modeling).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation der M2-Klassenstruktur zur Konfiguration des UDS-Dienstes <em>RequestFileTransfer</em> (SID 0x38 gemäß ISO 14229-1) innerhalb des AUTOSAR Diagnostic Extract Templates (<code>AUTOSAR_TPS_DiagnosticExtractTemplate</code>, Release R4.2.2). Das Modell trennt generische Dienstdefinitionen (Klassenebene) von der konkreten ECU-spezifischen Ausprägung (Instanzebene) sowie der Zugriffsrechteverwaltung (Sessions, Security Access).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Metaklassen:</strong></li>\n<li><code>DiagnosticServiceClass</code> <em>(abstract)</em>: Basisklasse aller UDS-Dienstklassen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticServiceInstance</code> <em>(abstract)</em>: Basisklasse für konkrete Dienstinstanzen; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticAccessPermission</code>: Definiert Sicherheitsstufen (<code>DiagnosticSecurityLevel</code>) und Diagnose-Sitzungen (<code>DiagnosticSession</code>), unter denen der Zugriff erlaubt ist; erbt von <code>DiagnosticCommonElement</code>.</li>\n<li><code>DiagnosticRequestFileTransferClass</code>: Konkrete Spezialisierung von <code>DiagnosticServiceClass</code> für SID 0x38.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Konkrete Spezialisierung von <code>DiagnosticServiceInstance</code> für SID 0x38.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Beziehungen, Assoziationen & Kardinalitäten:</strong></li>\n<li><strong>Vererbungen (Generalization):</strong></li>\n<li><code>DiagnosticRequestFileTransfer</code> $\\rightarrow$ <code>DiagnosticServiceInstance</code></li>\n<li><code>DiagnosticRequestFileTransferClass</code> $\\rightarrow$ <code>DiagnosticServiceClass</code></li>\n<li><strong>Klassen-/Instanz-Kopplung:</strong></li>\n<li><code>DiagnosticServiceInstance</code> referenziert <code>DiagnosticServiceClass</code> über Rolle <code>+serviceClass</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«atpAbstract»</code>).</li>\n<li><code>DiagnosticRequestFileTransfer</code> redefiniert diese Assoziation auf die konkrete Klasse <code>DiagnosticRequestFileTransferClass</code> über Rolle <code>+requestFileTransferClass</code> (Kardinalität <code>0..1</code>, Eigenschaft <code>{redefines serviceClass}</code>).</li>\n<li><strong>Zugriffssteuerungs-Assoziation (<code>+accessPermission</code>, Kardinalität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>):</strong></li>\n<li>Assoziation von <code>DiagnosticServiceInstance</code> zu <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-spezifische Auswertung:</strong> Als statisches M2-Strukturdiagramm enthält das Schaubild keine direkten Laufzeitsequenzen; es steuert jedoch die Validierungslogik im BSW-Diagnosestack (<code>Dcm</code>):</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Anfrage-Validierung:</strong> Bei Empfang einer UDS-PDU mit SID 0x38 identifiziert der <code>Dcm</code> die zugehörige Instanz (<code>DiagnosticRequestFileTransfer</code>).</li>\n<li><strong>Zugriffsprüfung:</strong> Validierung gegen die auf Instanzebene (<code>DiagnosticServiceInstance</code>) zugeordnete <code>DiagnosticAccessPermission</code> (aktive Session und Security Level). Bei Nichtübereinstimmung erfolgt die NRC-Rückmeldung (z. B. <code>0x33 SecurityAccessDenied</code> oder <code>0x7E SubFunctionNotSupportedInActiveSession</code>).</li>\n<li><strong>Dispatchen:</strong> Bei positivem Befund Weiterleitung der Dateitransfer-Parameter (z. B. AddFile, DeleteFile, ReadFile) an die zugeordnete Applikations- oder Speicherschnittstelle.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>DEXT-Generierung & BSW-Konfiguration (TPS_DEXT_01090):</strong></li>\n<li>DEXT-Importfilter müssen <code>DiagnosticRequestFileTransfer</code> zwingend mit genau einer Instanz von <code>DiagnosticRequestFileTransferClass</code> verknüpfen (<code>Kardinalität 1</code>).</li>\n<li>Die BSW-Generierung übersetzt diese M2-Elemente in die BSW-Konfigurationsstrukturen des <code>Dcm</code> (z. B. <code>DcmDsdService</code>, <code>DcmDsdServiceRow</code>).</li>\n<li><strong>Zugriffsrechte-Konsistenz (<code>accessPermissionValidity</code>):</strong></li>\n<li>Konfigurationswerkzeuge müssen sicherstellen: Ist <code>accessPermissionValidity</code> auf Instanzebene gesetzt, muss <code>DiagnosticRequestFileTransfer.accessPermission</code> definiert sein; ist sie auf Klassenebene gesetzt, muss <code>DiagnosticRequestFileTransferClass.accessPermission</code> gepflegt sein. Konflikte oder inkonsistente Redefinitionen führen zu Schema- bzw. Modellvalidierungsfehlern.</li>\n<li><strong>Applikationsvertrag:</strong></li>\n<li>Für eingebettete Entwickler bestimmt die Instanziierung von <code>DiagnosticRequestFileTransfer</code>, ob der Dienst 0x38 im Dcm-Dispatching aktiviert wird und welche Callback-/Port-Interfaces (<code>Dcm_RequestFileTransfer</code> bzw. entsprechende RTE-Ports) zur Verarbeitung des Dateisystems auf Applikationsebene implementiert werden müssen.</li>\n</ul>"}], "trans": [{"from": "FIG-e423410c9c08e452", "to": "FIG-eeae68f3e72758d0", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eeae68f3e72758d0", "to": "FIG-e5517727d9f9a55a", "fr": "R4.3.1", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticServiceClass</code>: Attribut <code>accessPermissionValidity : DiagnosticAccessPermissionValidityEnum</code> entfällt.</li>\n<li><code>DiagnosticServiceClass</code>: Assoziation <code>+accessPermission</code> (Kardinalität <code>0..1</code>) zu <code>DiagnosticAccessPermission</code> entfällt.</li>\n<li><code>DiagnosticRequestFileTransfer</code>: Kardinalität der Assoziation <code>+requestFileTransferClass</code> zu <code>DiagnosticRequestFileTransferClass</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-e5517727d9f9a55a", "to": "FIG-9c0ab4fcccb0161c", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9c0ab4fcccb0161c", "to": "FIG-86000bdc9202ee87", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticServiceInstance</code>: Assoziation <code>+accessPermission</code> zu <code>DiagnosticAccessPermission</code> um den Stereotyp <code>«atpSplitable»</code> ergänzt.</li>\n</ul>"}]};
